const listAbandonedDrafts = `-- name: ListAbandonedDrafts :many
SELECT id FROM projects
WHERE status = 'draft' AND updated_at < now() - make_interval(days => $1::int)
ORDER BY updated_at
LIMIT 200
`

// Rascunhos sem nenhuma alteração há mais de N dias (retenção). Só rascunhos: projeto enviado nunca é apagado por tempo.
func (q *Queries) ListAbandonedDrafts(ctx context.Context, olderThanDays int32) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listAbandonedDrafts, olderThanDays)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

